options(shiny.maxRequestSize=30*1024^2)
if (!requireNamespace('shiny',quietly=TRUE)) stop('Install shiny')
library(shiny)
ui <- fluidPage(tags$head(tags$style(HTML('body{background:#f5f7fb;font-family:Arial,"Microsoft YaHei"}.well{background:white;border-radius:12px}h2{color:#15345b}'))),titlePanel('Meta Analysis Studio V0.2 · R 本地分析'),sidebarLayout(sidebarPanel(fileInput('file','导入 CSV 数据（UTF-8）',accept='.csv'),selectInput('type','数据类型',c('连续型结局（两组均值/SD）'='continuous','二分类结局（事件数/总人数）'='binary','已计算效应量 yi / vi'='generic')),uiOutput('measure'),checkboxInput('knha','Hartung-Knapp 调整',TRUE),actionButton('run','运行 R 分析',class='btn-primary'),hr(),downloadButton('script','下载本次 R 分析脚本'),p('本机运行；不会将研究数据上传到互联网。')),mainPanel(tabsetPanel(tabPanel('数据检查',verbatimTextOutput('validation'),tableOutput('preview')),tabPanel('统计结果',verbatimTextOutput('results')),tabPanel('森林图',plotOutput('forest',height='550px'),downloadButton('png','导出森林图 PNG')),tabPanel('分析记录',verbatimTextOutput('session'))))))
server <- function(input,output,session){
 output$measure <- renderUI({selectInput('measure','效应量',switch(input$type,continuous=c('均值差 MD'='MD','标准化均值差 Hedges g'='SMD'),binary=c('风险比 RR'='RR','比值比 OR'='OR'),generic=c('通用效应量'='GEN')))})
 data <- reactive({req(input$file);read.csv(input$file$datapath,check.names=FALSE,stringsAsFactors=FALSE,fileEncoding='UTF-8-BOM')})
 required <- reactive({switch(input$type,continuous=c('study_id','n_t','mean_t','sd_t','n_c','mean_c','sd_c'),binary=c('study_id','event_t','n_t','event_c','n_c'),generic=c('study_id','yi','vi'))})
 check <- reactive({d<-data();missing<-setdiff(required(),names(d));if(length(missing))return(paste('缺少列:',paste(missing,collapse=', ')));if(nrow(d)<2)return('至少需要两项独立研究');if(anyNA(d[,required(),drop=FALSE]))return('必需字段存在缺失值');if(anyDuplicated(d$study_id))return('study_id 重复：请先核查多臂、重复发表或多效应量');cols<-setdiff(required(),'study_id');if(any(!is.finite(as.matrix(data.frame(lapply(d[,cols,drop=FALSE],as.numeric))))))return('数值字段存在非数值或非有限值');if(input$type=='continuous' && (any(d$n_t<2|d$n_c<2|d$sd_t<=0|d$sd_c<=0)))return('连续型数据要求 n≥2、SD>0');if(input$type=='binary' && (any(d$n_t<=0|d$n_c<=0|d$event_t<0|d$event_c<0|d$event_t>d$n_t|d$event_c>d$n_c)))return('事件数或总人数不合法');if(input$type=='generic' && any(d$vi<=0))return('方差 vi 必须大于零');'检查通过。请进一步人工确认研究独立性、结局方向、量表一致性与组间比较。'})
 output$validation<-renderText({req(input$file);check()});output$preview<-renderTable({head(data(),15)})
 fit <- eventReactive(input$run,{validate(need(check()=='检查通过。请进一步人工确认研究独立性、结局方向、量表一致性与组间比较。',check()));validate(need(requireNamespace('metafor',quietly=TRUE),'请先安装 metafor'));d<-data();if(input$type=='continuous'){m<-if(input$measure=='MD')'MD' else 'SMD';e<-metafor::escalc(measure=m,m1i=mean_t,sd1i=sd_t,n1i=n_t,m2i=mean_c,sd2i=sd_c,n2i=n_c,data=d)}else if(input$type=='binary'){m<-if(input$measure=='RR')'RR' else 'OR';e<-metafor::escalc(measure=m,ai=event_t,bi=n_t-event_t,ci=event_c,di=n_c-event_c,data=d,add=0.5,to='only0')}else{e<-d};f<-metafor::rma.uni(yi=e$yi,vi=e$vi,method='REML',test=if(input$knha)'knha' else 'z');list(f=f,d=d,e=e)})
 output$results<-renderPrint({x<-fit();print(summary(x$f));cat('\nPrediction interval:\n');print(predict(x$f));cat('\nNote: RR/OR are estimated on log scale; exponentiate for reporting.\n')})
 draw<-function(){x<-fit();metafor::forest(x$f,slab=x$d$study_id,header='Study',xlab=if(input$type=='binary')'Log effect (RR / OR)' else 'Effect size');title('Meta Analysis Studio V0.2')}
 output$forest<-renderPlot(draw());output$png<-downloadHandler(filename=function()'forest.png',content=function(file){png(file,width=2400,height=1800,res=300);draw();dev.off()})
 output$session<-renderPrint({print(sessionInfo());if(requireNamespace('metafor',quietly=TRUE))cat('\nmetafor:',as.character(packageVersion('metafor')),'\n')})
 output$script<-downloadHandler(filename=function()'analysis_script.R',content=function(file){req(input$file);d<-data();writeLines(c('# Analysis parameters',paste0('type <- "',input$type,'"'),paste0('measure <- "',input$measure,'"'),paste0('test <- "',if(input$knha)'knha' else 'z','"'),'# Original dataset must be retained separately.','library(metafor)','# See README for full reproducibility and audit instructions.'),file)})
}
shinyApp(ui,server)
